/// Offline fallback: real product model for a (VID, PID) pair.
/// Returns `None` when no seed exists (caller falls back to VID_BRAND).
pub(crate) fn lookup_pid_model(vid: &str, pid: &str) -> Option<&'static str> {
    let vid = vid.to_ascii_uppercase();
    let pid = pid.to_ascii_uppercase();
    PID_MODEL
        .iter()
        .find(|entry| entry.0 == vid.as_str() && entry.1 == pid.as_str())
        .map(|(_, _, m)| *m)
}
